mapper.update:
UPDATE t_note_content_saga
SET attempt_count = attempt_count + 1,
    lease_owner = #{owner}, lease_until = #{leaseUntil},
    lease_version = lease_version + 1, updated_time = #{now}
WHERE id = #{id}
  AND status IN ('PENDING', 'DELETE_PENDING', 'COMPENSATION_PENDING')
  AND (lease_until IS NULL OR lease_until <= #{now})
  AND next_attempt_at <= #{now}

UPDATE t_note_content_saga
SET status = 'COMPLETED', payload = NULL, completed_time = #{now},
    lease_owner = NULL, lease_until = NULL, last_error = NULL, updated_time = #{now}
WHERE id = #{id} AND status IN ('PENDING', 'DELETE_PENDING', 'COMPENSATION_PENDING')
  AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_note_content_saga
SET status = 'DELETE_PENDING', content_uuid = #{contentUuid}, payload = NULL,
    next_attempt_at = #{now}, last_error = NULL,
    lease_owner = NULL, lease_until = NULL, updated_time = #{now}
WHERE id = #{id} AND status = 'PENDING'
  AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_note_content_saga
SET status = 'COMPENSATION_PENDING', content_uuid = #{contentUuid}, payload = NULL,
    next_attempt_at = #{now}, last_error = #{error},
    lease_owner = NULL, lease_until = NULL, updated_time = #{now}
WHERE id = #{id} AND status = 'PENDING'
  AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_note_content_saga
SET status = 'ROLLED_BACK', payload = NULL, completed_time = #{now},
    lease_owner = NULL, lease_until = NULL, last_error = NULL, updated_time = #{now}
WHERE id = #{id} AND status = 'COMPENSATION_PENDING'
  AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_note_content_saga
SET next_attempt_at = #{nextAttemptAt}, last_error = #{error},
    lease_owner = NULL, lease_until = NULL, updated_time = #{now}
WHERE id = #{id} AND status IN ('PENDING', 'DELETE_PENDING', 'COMPENSATION_PENDING')
  AND lease_owner = #{owner} AND lease_version = #{leaseVersion}
